css:
:root{--navy:#0B2E40;--char:#11415A;--deep:#072433;--aqua:#00C2DE;--aqua-ink:#047A8B;
 --aqua-lite:#6FE6F2;--sky:#E6F7FB;--sky-line:#C3E9F1;--amber:#FFAC17;--page:#FFFFFF;
 --ink:#16323F;--slate:#577280;--line:#DCE7EC;--ondark:#DCEFF4;--ondark-mute:#A4C4CF;
 --fh:Archivo,"Helvetica Neue",Arial,sans-serif;--fb:Inter,"Helvetica Neue",Arial,sans-serif;
 --max:1080px}
*{box-sizing:border-box}
body{margin:0;background:var(--page);color:var(--ink);font:400 17px/1.72 var(--fb);
 -webkit-font-smoothing:antialiased}
.w{max-width:var(--max);margin:0 auto;padding:0 28px}
header.top{background:linear-gradient(160deg,#0B2E40 0%,#11415A 60%,#0B2E40 100%);
 color:var(--ondark);padding:56px 0 52px}
header.top h1{font:800 clamp(28px,4vw,44px)/1.1 var(--fh);color:#fff;margin:0 0 14px;
 letter-spacing:-.02em}
header.top p{margin:0;max-width:62ch;color:var(--ondark);font-size:18.5px}
.kick{display:inline-block;margin:0 0 18px;padding:7px 15px;border-radius:999px;
 background:rgba(0,194,222,.15);border:1px solid rgba(111,230,242,.25);
 font:700 12px/1 var(--fh);letter-spacing:.14em;text-transform:uppercase;color:var(--aqua-lite)}
h2{font:800 clamp(23px,2.6vw,31px)/1.2 var(--fh);color:var(--navy);letter-spacing:-.018em;
 margin:58px 0 8px;padding-top:26px;border-top:3px solid var(--aqua)}
h3{font:700 20px/1.3 var(--fh);color:var(--navy);margin:34px 0 10px;letter-spacing:-.01em}
h4{font:700 16.5px/1.35 var(--fh);color:var(--navy);margin:24px 0 8px}
p{margin:0 0 18px}
a{color:var(--aqua-ink);font-weight:600;text-decoration:none;border-bottom:1px solid var(--sky-line)}
a:hover{border-bottom-color:var(--aqua-ink)}
code,kbd{font:600 14.5px/1.5 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
 background:var(--sky);padding:2px 7px;border-radius:5px;color:var(--navy);
 border:1px solid var(--sky-line);overflow-wrap:break-word}
/* The chip's side padding was pushing a following full stop or comma away from
   it, so a sentence ending in a path read as "index.html ." Negative margin
   pulls the punctuation back without moving the chip itself. */
code + .pun,code{margin-right:0}
.pun{margin-left:-5px}
/* A narrow screen squeezed the table columns until a path inside a code span
   broke into single characters. The table keeps a readable minimum and the
   wrapper scrolls instead. */
@media (max-width:760px){
 .wrapT{overflow-x:auto;-webkit-overflow-scrolling:touch}
 .wrapT table{min-width:620px}
 .wrapT code{overflow-wrap:normal}
}
pre{background:var(--navy);color:var(--ondark);padding:20px 24px;border-radius:12px;
 overflow-x:auto;font:400 14.5px/1.7 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}
pre code{background:none;border:0;color:inherit;padding:0}
ul,ol{margin:0 0 20px;padding-left:0;list-style:none}
ul li{position:relative;padding:6px 0 6px 26px}
ul li::before{content:"";position:absolute;left:3px;top:16px;width:8px;height:8px;
 border-radius:50%;background:var(--aqua)}
ol{counter-reset:n}
ol li{position:relative;counter-increment:n;padding:6px 0 6px 34px}
ol li::before{content:counter(n);position:absolute;left:0;top:6px;width:24px;height:24px;
 border-radius:7px;background:var(--sky);border:1px solid var(--sky-line);color:var(--aqua-ink);
 font:800 12.5px/22px var(--fh);text-align:center}
table{width:100%;border-collapse:collapse;margin:0 0 24px;font-size:15.6px}
th,td{text-align:left;vertical-align:top;padding:13px 16px;border-top:1px solid var(--line)}
thead th{background:var(--navy);color:#fff;border-top:0;font:700 14.5px/1.4 var(--fh)}
tbody tr:nth-child(even) td{background:var(--sky)}
tbody th{font-weight:700;color:var(--navy);width:26%}
.wrapT{overflow-x:auto;border:1px solid var(--line);border-radius:12px}
.wrapT table{margin:0}
.box{background:var(--sky);border:1px solid var(--sky-line);border-radius:12px;
 padding:22px 26px;margin:0 0 24px}
.box.warn{background:#FFF6E6;border-color:#FFD98A}
.box.stop{background:#FFF0F0;border-color:#F3B5B5}
.box h4{margin-top:0}
.box p:last-child,.box ul:last-child{margin-bottom:0}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:18px;
 margin:0 0 26px}
.card{border:1px solid var(--line);border-radius:12px;padding:22px 22px 18px}
.card b{display:block;font:700 17px/1.3 var(--fh);color:var(--navy);margin-bottom:7px}
.card span{font-size:15.4px;color:var(--slate)}
.m{color:var(--slate);font-size:15.5px}
footer.end{margin-top:70px;padding:34px 0 50px;border-top:1px solid var(--line);
 color:var(--slate);font-size:14.6px}
@media (max-width:620px){.w{padding:0 20px}header.top{padding:40px 0 38px}}
